window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-63268c6e435164a1"]={"versions": [{"id": "FIG-63268c6e435164a1", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm mit <code>loop</code>- und <code>opt</code>-Fragmenten).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Communication Stack (ComStack).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung des Empfangspfads (<code>Rx Indication</code>) im FlexRay Interface (<code>FrIf</code>). Das Diagramm spezifiziert die zyklus- bzw. zeitgesteuerte Weiterreichung empfangener FlexRay-Frames und deren enthaltener PDUs (Protocol Data Units) aus dem lokalen FrIf-Puffer an übergeordnete Schichten (z. B. <code>PduR</code>, <code>FrTp</code>, <code>FrNm</code>) im Rahmen der FlexRay-Joblistenabarbeitung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lifelines & Komponenten:</strong></li>\n<li><code>Interrupt Service Routine</code> (ISR): Auslösender Kontext (z. B. FlexRay-Timer-Interrupt oder Controller-Event-ISR), der die deterministische Slot-/Joblisten-Verarbeitung triggert.</li>\n<li><code>«module» FrIf</code>: FlexRay Interface; zuständig für Joblist-Scheduling, Entpacken von PDUs aus FlexRay-Frames, Pufferung und Adressauflösung.</li>\n<li><code>Upper Layer for FrIf</code>: Generischer Empfänger über dem FrIf (z. B. <code>PduR</code> via <code>PduR_FrIfRxIndication</code>, <code>FrTp</code> via <code>FrTp_RxIndication</code>, <code>FrNm</code> oder CDD).</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code>: Clusterspezifische Hauptfunktion zur Joblisten-Ausführung, aufgerufen aus dem ISR-Kontext.</li>\n<li><code>&lt;UL_RxIndication&gt;(PduIdType, const uint8*)</code>: Konfigurierter synchroner Rx-Callback des Upper Layers mit PDU-Identifikator und Zeiger auf den SDU-Puffer (<code>FrIf_SduPtr</code>).</li>\n<li><strong>Interne Entitäten & Status:</strong></li>\n<li><code>Fr_RxPduId</code>: Eindeutige PDU-ID zur Identifikation der empfangenen Nachricht und des Zielmoduls.</li>\n<li><code>FrIf_SduPtr</code>: Lokaler Datenzeiger auf den PDU-Puffer im <code>FrIf</code>.</li>\n<li><code>\"up-to-date\"</code>-Statusflag: Gibt an, ob der Puffer im aktuellen Kommunikationszyklus mit neuen Payload-Daten aus dem FlexRay-Controller aktualisiert wurde (Update-Bit-Semantik).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Die <code>Interrupt Service Routine</code> ruft synchron <code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code> auf, um die anstehenden Jobs für das konfigurierte FlexRay-Cluster abzuarbeiten.</li>\n<li><strong>Iterationsschleife (<code>loop For each PDU in this Frame</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das <code>FrIf</code> iteriert über alle im aktuellen FlexRay-Frame gemappten PDUs (Frame-De-Multiplexing / PDU-Extraction).</li>\n<li><strong>PDU-Auflösung:</strong> Interner Aufruf <code>Determine Fr_RxPduId and PDU-owning Upper Layer()</code> ermittelt die Ziel-PDU-ID und das zuständige Upper-Layer-Modul.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bedingte Weiterleitung (<code>opt PDU is marked as \"up-to-date\"</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nur wenn für die PDU frische Daten vorliegen (Puffer als <em>up-to-date</em> markiert), wird der Zweig ausgeführt; veraltete oder nicht aktualisierte PDU-Instanzen werden verworfen.</li>\n<li><strong>Puffer-Bereitstellung:</strong> <code>Set FrIf_SduPtr to PDU's local buffer in the FrIf()</code> setzt den Nutzdatenzeiger auf das interne Byte-Array.</li>\n<li><strong>Upper-Layer-Indikation:</strong> Synchroner Aufruf <code>&lt;UL_RxIndication&gt;(PduIdType, const uint8*)</code> an die obere Schicht.</li>\n<li><strong>Payload-Verarbeitung:</strong> Der Upper Layer führt <code>Copy PDU to internal location and process PDU()</code> aus (Zero-Copy ist temporär auf den Callback beschränkt; Daten müssen vor Verlassen gesichert werden).</li>\n<li><strong>Quittierung:</strong> Nach Rückkehr des Callbacks führt das <code>FrIf</code> <code>Reset Information that PDU's FrIf buffer has been updated()</code> aus, um ein wiederholtes Indizieren alter Daten im Folgezyklus zu verhindern.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Nach Durchlauf aller PDUs terminiert die Joblisten-Ausführung und kehrt zur ISR zurück.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungskontext & Latenz:</strong> Der gesamte Ablauf findet synchron im Kontext der <code>Interrupt Service Routine</code> (oder eines High-Priority-Tasks) statt. Der Callback <code>&lt;UL_RxIndication&gt;</code> darf keinesfalls blockieren oder zeitintensive Operationen ausführen, um den zeitkritischen FlexRay-Kommunikationszyklus nicht zu destabilisieren.</li>\n<li><strong>Puffer-Lebensdauer & Gültigkeit:</strong> Der an <code>&lt;UL_RxIndication&gt;</code> übergebene Zeiger (<code>const uint8*</code>) verweist direkt in den lokalen FrIf-Puffer. Die Gültigkeit ist strikt auf die Ausführungsdauer des Callbacks beschränkt. Der Upper Layer muss die Payload synchron in eigene Puffer kopieren (<code>Copy PDU to internal location</code>).</li>\n<li><strong>Konfigurationsverträge (BSW-Konfiguration):</strong></li>\n<li>Zuordnung von Frame-Layout, PDUs und PDU-Payload-Offsets im FlexRay-Cluster.</li>\n<li>Konfiguration der Ziel-Callbacks in <code>FrIf</code> via <code>FrIfRxPduUserRxIndicationName</code> (z. B. <code>PduR_FrIfRxIndication</code>).</li>\n<li><strong>Update-Bit-Semantik:</strong> Das Resetten des Update-Status garantiert Data-Consistency und vermeidet Duplikate bei statisch repetitiven FlexRay-Slots, wenn der Sender in einem Zyklus keine neuen Nutzdaten bereitgestellt hat.</li>\n</ul>"}, {"id": "FIG-11d73bf66e06f2ba", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm mit <code>loop</code>- und <code>opt</code>-Fragmenten).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Communication Stack (ComStack).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung des Empfangspfads (<code>Rx Indication</code>) im FlexRay Interface (<code>FrIf</code>). Das Diagramm spezifiziert die zyklus- bzw. zeitgesteuerte Weiterreichung empfangener FlexRay-Frames und deren enthaltener PDUs (Protocol Data Units) aus dem lokalen FrIf-Puffer an das übergeordnete Modul <code>LSduR</code> im Rahmen der FlexRay-Joblistenabarbeitung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lifelines & Komponenten:</strong></li>\n<li><code>Interrupt Service Routine</code> (ISR): Auslösender Kontext (z. B. FlexRay-Timer-Interrupt oder Controller-Event-ISR), der die deterministische Slot-/Joblisten-Verarbeitung triggert.</li>\n<li><code>«module» FrIf</code>: FlexRay Interface; zuständig für Joblist-Scheduling, Entpacken von PDUs aus FlexRay-Frames, Pufferung und Adressauflösung.</li>\n<li><code>«module» LSduR</code>: Large SDU Router als spezifischer Empfänger über dem FrIf.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code>: Clusterspezifische Hauptfunktion zur Joblisten-Ausführung, aufgerufen aus dem ISR-Kontext.</li>\n<li><code>LSduR_FrIfRxIndication()</code>: Konfigurierter synchroner Rx-Callback des LSduR-Moduls.</li>\n<li><strong>Interne Entitäten & Status:</strong></li>\n<li><code>Fr_RxPduId</code>: Eindeutige PDU-ID zur Identifikation der empfangenen Nachricht und des Zielmoduls.</li>\n<li><code>FrIf_SduPtr</code>: Lokaler Datenzeiger auf den PDU-Puffer im <code>FrIf</code>.</li>\n<li><code>\"up-to-date\"</code>-Statusflag: Gibt an, ob der Puffer im aktuellen Kommunikationszyklus mit neuen Payload-Daten aus dem FlexRay-Controller aktualisiert wurde (Update-Bit-Semantik).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Die <code>Interrupt Service Routine</code> ruft synchron <code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code> auf, um die anstehenden Jobs für das konfigurierte FlexRay-Cluster abzuarbeiten.</li>\n<li><strong>Iterationsschleife (<code>loop For each PDU in this Frame</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das <code>FrIf</code> iteriert über alle im aktuellen FlexRay-Frame gemappten PDUs (Frame-De-Multiplexing / PDU-Extraction).</li>\n<li><strong>PDU-Auflösung:</strong> Interner Aufruf <code>Determine Fr_RxPduId and PDU-owning Upper Layer()</code> ermittelt die Ziel-PDU-ID und das zuständige Upper-Layer-Modul.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bedingte Weiterleitung (<code>opt PDU is marked as \"up-to-date\"</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nur wenn für die PDU frische Daten vorliegen (Puffer als <em>up-to-date</em> markiert), wird der Zweig ausgeführt; veraltete oder nicht aktualisierte PDU-Instanzen werden verworfen.</li>\n<li><strong>Puffer-Bereitstellung:</strong> <code>Set FrIf_SduPtr to PDU's local buffer in the FrIf()</code> setzt den Nutzdatenzeiger auf das interne Byte-Array.</li>\n<li><strong>Upper-Layer-Indikation:</strong> Synchroner Aufruf <code>LSduR_FrIfRxIndication()</code> an das Modul <code>LSduR</code>.</li>\n<li><strong>Payload-Verarbeitung:</strong> Das <code>LSduR</code> führt <code>Copy PDU to internal location and process PDU()</code> aus (Zero-Copy ist temporär auf den Callback beschränkt; Daten müssen vor Verlassen gesichert werden).</li>\n<li><strong>Quittierung:</strong> Nach Rückkehr des Callbacks führt das <code>FrIf</code> <code>Reset Information that PDU's FrIf buffer has been updated()</code> aus, um ein wiederholtes Indizieren alter Daten im Folgezyklus zu verhindern.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Nach Durchlauf aller PDUs terminiert die Joblisten-Ausführung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchroner ISR-Kontext:</strong> Da der Indikations-Callback <code>LSduR_FrIfRxIndication()</code> synchron innerhalb von <code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code> aus dem ISR-Kontext aufgerufen wird, müssen die Operationen im <code>LSduR</code> zeiteffizient und nicht-blockierend ausgeführt werden.</li>\n<li><strong>Puffergültigkeit und Kopiersemantik:</strong> Der Zeiger <code>FrIf_SduPtr</code> verweist auf den lokalen Puffer des <code>FrIf</code> und ist nur während der Dauer des synchronen Aufrufs gültig. Das <code>LSduR</code> muss Nutzdaten vor der Rückkehr lokal sichern (<code>Copy PDU to internal location</code>).</li>\n<li><strong>Konsistenz durch Update-Flags:</strong> Die Abfrage und das anschließende Rücksetzen des Update-Status verhindern die mehrfache Indikation identischer Nutzdaten in nachfolgenden Joblistenzyklen.</li>\n</ul>"}, {"id": "FIG-b18755c467adb8df", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm mit <code>loop</code>- und <code>opt</code>-Fragmenten).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Communication Stack (ComStack).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung des Empfangspfads (<code>Rx Indication</code>) im FlexRay Interface (<code>FrIf</code>). Das Diagramm spezifiziert die zyklus- bzw. zeitgesteuerte Weiterreichung empfangener FlexRay-Frames und deren enthaltener PDUs (Protocol Data Units) aus dem lokalen FrIf-Puffer an das übergeordnete Modul <code>LSduR</code> im Rahmen der FlexRay-Joblistenabarbeitung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lifelines & Komponenten:</strong></li>\n<li><code>Interrupt Service Routine</code> (ISR): Auslösender Kontext (z. B. FlexRay-Timer-Interrupt oder Controller-Event-ISR), der die deterministische Slot-/Joblisten-Verarbeitung triggert.</li>\n<li><code>«module» FrIf</code>: FlexRay Interface; zuständig für Joblist-Scheduling, Entpacken von PDUs aus FlexRay-Frames, Pufferung und Adressauflösung.</li>\n<li><code>«module» LSduR</code>: Large SDU Router als spezifischer Empfänger über dem FrIf.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code>: Clusterspezifische Hauptfunktion zur Joblisten-Ausführung, aufgerufen aus dem ISR-Kontext.</li>\n<li><code>LSduR_FrIfRxIndication()</code>: Konfigurierter synchroner Rx-Callback des LSduR-Moduls.</li>\n<li><strong>Interne Entitäten & Status:</strong></li>\n<li><code>Fr_RxPduId</code>: Eindeutige PDU-ID zur Identifikation der empfangenen Nachricht und des Zielmoduls.</li>\n<li><code>FrIf_SduPtr</code>: Lokaler Datenzeiger auf den PDU-Puffer im <code>FrIf</code>.</li>\n<li><code>\"up-to-date\"</code>-Statusflag: Gibt an, ob der Puffer im aktuellen Kommunikationszyklus mit neuen Payload-Daten aus dem FlexRay-Controller aktualisiert wurde (Update-Bit-Semantik).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Die <code>Interrupt Service Routine</code> ruft synchron <code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code> auf, um die anstehenden Jobs für das konfigurierte FlexRay-Cluster abzuarbeiten.</li>\n<li><strong>Iterationsschleife (<code>loop For each PDU in this Frame</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das <code>FrIf</code> iteriert über alle im aktuellen FlexRay-Frame gemappten PDUs (Frame-De-Multiplexing / PDU-Extraction).</li>\n<li><strong>PDU-Auflösung:</strong> Interner Aufruf <code>Determine Fr_RxPduId and PDU-owning Upper Layer()</code> ermittelt die Ziel-PDU-ID und das zuständige Upper-Layer-Modul.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bedingte Weiterleitung (<code>opt PDU is marked as \"up-to-date\"</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nur wenn für die PDU frische Daten vorliegen (Puffer als <em>up-to-date</em> markiert), wird der Zweig ausgeführt; veraltete oder nicht aktualisierte PDU-Instanzen werden verworfen.</li>\n<li><strong>Puffer-Bereitstellung:</strong> <code>Set FrIf_SduPtr to PDU's local buffer in the FrIf()</code> setzt den Nutzdatenzeiger auf das interne Byte-Array.</li>\n<li><strong>Upper-Layer-Indikation:</strong> Synchroner Aufruf <code>LSduR_FrIfRxIndication()</code> an das Modul <code>LSduR</code>.</li>\n<li><strong>Payload-Verarbeitung:</strong> Das <code>LSduR</code> führt <code>Copy PDU to internal location and process PDU()</code> aus (Zero-Copy ist temporär auf den Callback beschränkt; Daten müssen vor Verlassen gesichert werden).</li>\n<li><strong>Quittierung:</strong> Nach Rückkehr des Callbacks führt das <code>FrIf</code> <code>Reset Information that PDU's FrIf buffer has been updated()</code> aus, um ein wiederholtes Indizieren alter Daten im Folgezyklus zu verhindern.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Nach Durchlauf aller PDUs terminiert die Joblisten-Ausführung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchroner ISR-Kontext:</strong> Da der Indikations-Callback <code>LSduR_FrIfRxIndication()</code> synchron innerhalb von <code>FrIf_JobListExec_&lt;FrIfCluster.ShortName&gt;()</code> aus dem ISR-Kontext aufgerufen wird, müssen die Operationen im <code>LSduR</code> zeiteffizient und nicht-blockierend ausgeführt werden.</li>\n<li><strong>Puffergültigkeit und Kopiersemantik:</strong> Der Zeiger <code>FrIf_SduPtr</code> verweist auf den lokalen Puffer des <code>FrIf</code> und ist nur während der Dauer des synchronen Aufrufs gültig. Das <code>LSduR</code> muss Nutzdaten vor der Rückkehr lokal sichern (<code>Copy PDU to internal location</code>).</li>\n<li><strong>Konsistenz durch Update-Flags:</strong> Die Abfrage und das anschließende Rücksetzen des Update-Status verhindern die mehrfache Indikation identischer Nutzdaten in nachfolgenden Joblistenzyklen.</li>\n</ul>"}], "trans": [{"from": "FIG-63268c6e435164a1", "to": "FIG-11d73bf66e06f2ba", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Lifeline / Modul:</strong> Die generische obere Schicht <code>Upper Layer for FrIf</code> wurde durch das konkrete BSW-Modul <code>«module» LSduR</code> ersetzt.</li>\n<li><strong>Empfangsindikation (Schnittstelle):</strong> Der generische Aufruf <code>&lt;UL_RxIndication&gt;(PduIdType, const uint8*)</code> wurde durch den konkreten Schnittstellenaufruf <code>LSduR_FrIfRxIndication()</code> ersetzt.</li>\n<li><strong>Rückkehrnachricht:</strong> Die Beschriftung <code>&lt;UL_RxIndication&gt;()</code> auf der gestrichelten Rückkehrnachricht zum <code>FrIf</code> wurde entfernt (unbeschrifteter Rückkehrpfeil).</li>\n</ul>"}, {"from": "FIG-11d73bf66e06f2ba", "to": "FIG-b18755c467adb8df", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
